        self._company_teams: Optional[Dict[str, Dict[str, Any]]] = None
        self._project_teams: Optional[Dict[str, str]] = None
        self._boards: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self._tasks: Optional[List[Dict[str, Any]]] = None

    # ------------------------------------------------------------------
